		Pong pong;
	}
	statevars {
		int count;
	}

	Ping(Pong pong) {
		self.pong = pong;
		count = 0;
	}

	msgsrv StartMessage() {
		// Ping started the game!
		PingMessage();
	}

	msgsrv PingMessage() {
		// Not used in Ping
	}

	msgsrv PongMessage() {
		count = count + 1;
